    _mygoWrite_Kind(&w, v.kind)
    _mygoWrite_Level(&w, v.level)
}

func _mygoRead_Level(_ r: inout _MygoReader) throws -> Level {
    let raw = Int(truncatingIfNeeded: try r.i64())
    guard let v = Level(rawValue: raw) else { throw _MygoWireError.value("Level", "\(raw)") }
    return v
}

func _mygoWrite_Level(_ w: inout _MygoWriter, _ v: Level) {
    w.i64(Int64(truncatingIfNeeded: v.rawValue))
}

func _mygoRead_Moment(_ r: inout _MygoReader) throws -> Moment {
    return Moment(
        at: try r.date(),
        twice: try r.duration()
    )
}

func _mygoWrite_Moment(_ w: inout _MygoWriter, _ v: Moment) {
    w.date(v.at)
    w.duration(v.twice)
}

func _mygoRead_Record(_ r: inout _MygoReader) throws -> Record {
    return Record(
        name: try r.string(),
        counts: try _mygoRead_slice_int(&r),
        tags: try _mygoRead_map_string(&r),
        inner: try _mygoRead_Inner(&r),
        next: try _mygoRead_ptr_Inner(&r),
        kind: try _mygoRead_Kind(&r),
        data: try r.data()
    )
}

func _mygoWrite_Record(_ w: inout _MygoWriter, _ v: Record) {
    w.string(v.name)
    _mygoWrite_slice_int(&w, v.counts)
    _mygoWrite_map_string(&w, v.tags)
    _mygoWrite_Inner(&w, v.inner)
    _mygoWrite_ptr_Inner(&w, v.next)
    _mygoWrite_Kind(&w, v.kind)
    w.data(v.data)
}

func _mygoRead_Scalars(_ r: inout _MygoReader) throws -> Scalars {
    return Scalars(
        i: Int(truncatingIfNeeded: try r.i64()),
        i8: Int8(truncatingIfNeeded: try r.i64()),
        u16: UInt16(truncatingIfNeeded: try r.i64()),
        i32: Int32(truncatingIfNeeded: try r.i64()),
        u64: UInt64(truncatingIfNeeded: try r.i64()),
        f32: Float(try r.double()),
        f: try r.double(),
        b: try r.bool()
    )
}

func _mygoWrite_Scalars(_ w: inout _MygoWriter, _ v: Scalars) {
    w.i64(Int64(truncatingIfNeeded: v.i))
    w.i64(Int64(truncatingIfNeeded: v.i8))
    w.i64(Int64(truncatingIfNeeded: v.u16))
    w.i64(Int64(truncatingIfNeeded: v.i32))
    w.i64(Int64(truncatingIfNeeded: v.u64))
    w.double(Double(v.f32))
    w.double(v.f)
    w.bool(v.b)
}

func _mygoRead_Texts(_ r: inout _MygoReader) throws -> Texts {
    return Texts(
        s: try r.string(),
        b: try r.data()
    )
}

func _mygoWrite_Texts(_ w: inout _MygoWriter, _ v: Texts) {
    w.string(v.s)
    w.data(v.b)
}

func _mygoRead_map_int(_ r: inout _MygoReader) throws -> [String: Int] {
    let n = try r.count()
    var v: [String: Int] = [:]
    v.reserveCapacity(n)
    for _ in 0..<n {
        let k = try r.string()
        v[k] = Int(truncatingIfNeeded: try r.i64())
    }
    return v
}

func _mygoWrite_map_int(_ w: inout _MygoWriter, _ v: [String: Int]) {
    w.count(v.count)
    for (k, x) in v {
        w.string(k)
        w.i64(Int64(truncatingIfNeeded: x))
    }
}

func _mygoRead_map_string(_ r: inout _MygoReader) throws -> [String: String] {
    let n = try r.count()
    var v: [String: String] = [:]
    v.reserveCapacity(n)
    for _ in 0..<n {
        let k = try r.string()
        v[k] = try r.string()
    }
    return v
}

func _mygoWrite_map_string(_ w: inout _MygoWriter, _ v: [String: String]) {
    w.count(v.count)
    for (k, x) in v {
        w.string(k)
        w.string(x)
    }
}

func _mygoRead_ptr_Inner(_ r: inout _MygoReader) throws -> Inner? {
    if try r.bool() { return try _mygoRead_Inner(&r) }
    return nil
}

func _mygoWrite_ptr_Inner(_ w: inout _MygoWriter, _ v: Inner?) {
    if let x = v {
        w.bool(true)
        _mygoWrite_Inner(&w, x)
    } else {
        w.bool(false)
    }
}

func _mygoRead_ptr_int(_ r: inout _MygoReader) throws -> Int? {
    if try r.bool() { return Int(truncatingIfNeeded: try r.i64()) }
    return nil
}

func _mygoWrite_ptr_int(_ w: inout _MygoWriter, _ v: Int?) {
    if let x = v {
        w.bool(true)
        w.i64(Int64(truncatingIfNeeded: x))
    } else {
        w.bool(false)
    }
}

func _mygoRead_slice_Empty(_ r: inout _MygoReader) throws -> [Empty] {
    let n = try r.count()
    var v: [Empty] = []
    v.reserveCapacity(n)
    for _ in 0..<n { v.append(try _mygoRead_Empty(&r)) }
    return v
}

func _mygoWrite_slice_Empty(_ w: inout _MygoWriter, _ v: [Empty]) {
    w.count(v.count)
    for x in v { _mygoWrite_Empty(&w, x) }
}

func _mygoRead_slice_int(_ r: inout _MygoReader) throws -> [Int] {
    let n = try r.count()
    var v: [Int] = []
    v.reserveCapacity(n)
    for _ in 0..<n { v.append(Int(truncatingIfNeeded: try r.i64())) }
