}

func _mygoWrite_slice_int(_ w: inout _MygoWriter, _ v: [Int]) {
    w.count(v.count)
    for x in v { w.i64(Int64(truncatingIfNeeded: x)) }
}

func _mygoRead_slice_slice_int(_ r: inout _MygoReader) throws -> [[Int]] {
    let n = try r.count()
    var v: [[Int]] = []
    v.reserveCapacity(n)
    for _ in 0..<n { v.append(try _mygoRead_slice_int(&r)) }
    return v
}

func _mygoWrite_slice_slice_int(_ w: inout _MygoWriter, _ v: [[Int]]) {
